// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
        LogFile lf = new LogFile();
        c.SetLogFile(address(lf));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        // keep amount small enough that balances+msg.value never overflows and deposit is meaningful
        amount = bound(amount, 2, 1 ether);
        vm.assume(actor != address(c));
        vm.assume(actor != address(0));

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        // General rule: after depositing v, the credited balance equals v exactly.
        assertTrue(c.balances(actor) == amount);
    }
}

// Minimal log contract required so C's Deposit() does not revert on its external log call.
contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
